S = "Hakeem Force Academy"
QS = [
(S, "Who was the closest friend of the Holy Prophet (PBUH)?",
 ["Hazrat Umar (RA)", "Hazrat Abu Bakr Siddique (RA)", "Hazrat Ali (RA)", "Hazrat Usman (RA)"], 1,
 "Hazrat Abu Bakr Siddique (RA) was the Prophet's closest friend and the first man outside his family circle to accept Islam. He is called Siddique and Yar-e-Ghar (companion of the cave).",
 "Hazrat Abu Bakr (RA) was the first caliph of Islam and ruled from 11 AH to 13 AH.", 1),
(S, "Who accompanied the Holy Prophet (PBUH) during the Hijrat from Makkah to Madina?",
 ["Hazrat Ali (RA)", "Hazrat Umar (RA)", "Hazrat Bilal (RA)", "Hazrat Abu Bakr Siddique (RA)"], 3,
 "Hazrat Abu Bakr (RA) was the Prophet's companion on the Hijrat and shared the cave of Thaur with him. Hazrat Ali (RA) stayed behind in Makkah to return the trusts.",
 "Amir bin Fuhaira served as their helper and Abdullah bin Uraiqit as their guide on the journey.", 1),
(S, "Who was the commander of the Muslim army in the Ghazwa (Battle) of Tabuk?",
 ["Hazrat Khalid bin Walid (RA)", "Hazrat Ali (RA)", "Hazrat Muhammad (PBUH)", "Hazrat Abu Ubaidah (RA)"], 2,
 "The Ghazwa of Tabuk (9 AH) was a campaign in which the Holy Prophet (PBUH) himself led the Muslim army of about 30,000. A Ghazwa is by definition a battle in which the Prophet personally took part.",
 "Hazrat Ali (RA) was left in charge of Madina during the Tabuk expedition.", 5),
(S, "Who was the commander of the Quraysh army in the Battle of Uhud?",
 ["Abu Jahl", "Abu Sufyan", "Utbah bin Rabiah", "Ikrimah bin Abu Jahl"], 1,
 "Abu Sufyan bin Harb led the Makkan army of about 3,000 in 3 AH, because Abu Jahl had been killed at Badr. Khalid bin Walid commanded the cavalry wing.",
 "Abu Sufyan later accepted Islam at the conquest of Makkah in 8 AH.", 1),
(S, "Who was the first Ameer-ul-Momineen (Commander of the Faithful) in Islamic history?",
 ["Hazrat Abu Bakr (RA)", "Hazrat Umar Farooq (RA)", "Hazrat Usman (RA)", "Hazrat Ali (RA)"], 1,
 "Hazrat Abu Bakr (RA) was called Khalifa-tu-Rasul Allah, while Hazrat Umar (RA) was the first to be addressed as Ameer-ul-Momineen. Most Islamic history books record this.",
 "The title was adopted by later caliphs such as Hazrat Usman and Hazrat Ali (RA).", 1),
(S, "Who was the first child to accept Islam?",
 ["Hazrat Zaid bin Haritha (RA)", "Hazrat Ali (RA)", "Hazrat Zubair bin Awwam (RA)", "Hazrat Abdullah bin Abbas (RA)"], 1,
 "Hazrat Ali (RA), the cousin of the Prophet, accepted Islam as a boy of about 10 years old. He was raised in the Prophet's household.",
 "Hazrat Khadija (RA) was the first woman and Hazrat Abu Bakr (RA) the first free adult man to accept Islam.", 1),
(S, "Who was the first caliph of Islam?",
 ["Hazrat Umar (RA)", "Hazrat Ali (RA)", "Hazrat Usman (RA)", "Hazrat Abu Bakr Siddique (RA)"], 3,
 "After the Prophet (PBUH) passed away in 11 AH, the Muslims chose Hazrat Abu Bakr Siddique (RA) as their first caliph at Saqifa Bani Saida.",
 "The four Rashidun caliphs ruled in the order Abu Bakr, Umar, Usman and Ali (RA).", 1),
(S, "Who was the first muezzin (caller to prayer) of Islam?",
 ["Hazrat Bilal bin Rabah (RA)", "Hazrat Abdullah bin Umm Maktum (RA)", "Hazrat Abdullah bin Zaid (RA)", "Hazrat Saad bin Abi Waqqas (RA)"], 0,
 "Hazrat Bilal bin Rabah (RA), an Abyssinian companion, gave the first adhan in Madina after the Prophet approved it. Hazrat Abdullah bin Zaid (RA) saw the words of the adhan in a dream.",
 "Hazrat Bilal (RA) also gave the adhan from the roof of the Kaaba on the day Makkah was conquered.", 2),
(S, "Who was the first Pakistani to win a Nobel Prize?",
 ["Dr Abdus Salam", "Malala Yousafzai", "Dr Abdul Qadeer Khan", "Dr Ishfaq Ahmad"], 0,
 "Dr Abdus Salam won the Nobel Prize in Physics in 1979, shared with Glashow and Weinberg, for the electroweak theory. He was the first Pakistani and the first Muslim Nobel laureate in science.",
 "Malala Yousafzai won the Nobel Peace Prize in 2014 and is the youngest Nobel laureate.", 1),
(S, "Who was the first President of Pakistan?",
 ["Quaid-e-Azam Muhammad Ali Jinnah", "Ghulam Muhammad", "Iskander Mirza", "Field Marshal Ayub Khan"], 2,
 "Under the 1956 Constitution, Iskander Mirza became the first President of Pakistan on 23 March 1956. Before this, the head of state was the Governor General.",
 "Quaid-e-Azam and Ghulam Muhammad had served as Governor General, not as President.", 1),
(S, "Who was the first Pakistani woman to climb K2?",
 ["Naila Kiani", "Samina Baig", "Shaista Bano", "Maria Mirza"], 1,
 "Samina Baig reached the summit of K2 on 22 July 2022, a few hours before Naila Kiani. She was the first Pakistani woman to do so.",
 "Samina Baig had earlier climbed Mount Everest in 2013 and completed the Seven Summits in 2014.", 1),
(S, "Who was the first woman to travel to space?",
 ["Sally Ride", "Svetlana Savitskaya", "Valentina Tereshkova", "Kalpana Chawla"], 2,
 "Valentina Tereshkova of the Soviet Union flew aboard Vostok 6 in June 1963. She orbited the Earth 48 times.",
 "Sally Ride became the first American woman in space in 1983.", 1),
(S, "Who was the first woman officer of the Pakistan Army to be promoted to the rank of Lieutenant General (three-star)?",
 ["Lt Gen Nigar Johar", "Maj Gen Shahida Malik", "Brig Dr Shahida Hasan", "Lt Gen Samina Khan"], 0,
 "Lt Gen Nigar Johar of the Army Medical Corps was promoted in June 2020 and became the first woman in the Pakistan Army to reach three-star rank. She was also appointed the first female Surgeon General of the Pakistan Army.",
 "She is from Swabi in Khyber Pakhtunkhwa.", 1),
(S, "Who was the guarantor and third party that brokered the Indus Waters Treaty between India and Pakistan?",
 ["United Nations", "World Bank", "United States Congress", "International Court of Justice"], 1,
 "The World Bank mediated the long negotiations and signed the treaty as a party for certain provisions. The treaty was signed in Karachi on 19 September 1960.",
 "Some sources describe the World Bank's role as a broker rather than a strict guarantor.", 1),
(S, "Who was the head of state of Pakistan in 1960?",
 ["Iskander Mirza", "Yahya Khan", "Ghulam Muhammad", "Field Marshal Ayub Khan"], 3,
 "Ayub Khan took power in the October 1958 coup and was President of Pakistan in 1960. He remained in office until March 1969.",
 "Iskander Mirza, the first President, was removed by Ayub Khan in October 1958.", 1),
(S, "Who headed the committee that compiled the Holy Quran in one book during the caliphate of Hazrat Abu Bakr (RA)?",
 ["Hazrat Zaid bin Sabit (RA)", "Hazrat Ubayy bin Kab (RA)", "Hazrat Abdullah bin Masud (RA)", "Hazrat Ali (RA)"], 0,
 "Hazrat Abu Bakr (RA), on the advice of Hazrat Umar (RA) after the Battle of Yamama, assigned Hazrat Zaid bin Sabit (RA), the Prophet's scribe of revelation, to collect the Quran. He had memorised the Quran and written much of it down in the Prophet's lifetime.",
 "Hazrat Usman (RA) later had standard copies prepared from this compilation.", 3),
(S, "Who was the false prophet and enemy leader fought by the Muslims in the Battle of Yamama?",
 ["Musaylima Kazzab", "Aswad Ansi", "Tulaiha bin Khuwailid", "Sajah"], 0,
 "The Battle of Yamama in 12 AH was fought against the false claimant to prophethood Musaylima Kazzab and his tribe Banu Hanifa. The Muslim commander was Hazrat Khalid bin Walid (RA), and Musaylima was killed.",
 "Many Huffaz of the Quran were martyred at Yamama, which led to the compilation of the Quran.", 1),
(S, "Who led the Simla Deputation of 1906 that presented Muslim demands to the Viceroy Lord Minto?",
 ["Nawab Salimullah of Dhaka", "Sir Syed Ahmad Khan", "Sir Agha Khan III", "Quaid-e-Azam Muhammad Ali Jinnah"], 2,
 "The Simla Deputation of 1 October 1906 was led by Sir Sultan Muhammad Shah, Agha Khan III. It asked for separate electorates for Muslims.",
 "The All India Muslim League was founded a few months later in Dhaka in December 1906.", 1),
(S, "Who was the opponent of Field Marshal Ayub Khan in the 1965 presidential election of Pakistan?",
 ["Fatima Jinnah", "Chaudhry Muhammad Ali", "Zulfikar Ali Bhutto", "Hussain Shaheed Suhrawardy"], 0,
 "Miss Fatima Jinnah, sister of the Quaid-e-Azam, contested as the joint candidate of the Combined Opposition Parties in January 1965. Ayub Khan won through the Basic Democrats electoral college.",
 "She was known as Madar-e-Millat (Mother of the Nation).", 1),
(S, "Who signed the Indus Waters Treaty on behalf of Pakistan in 1960?",
 ["Liaquat Ali Khan", "Zulfikar Ali Bhutto", "Iskander Mirza", "Field Marshal Ayub Khan"], 3,
 "President Ayub Khan signed the treaty for Pakistan in Karachi on 19 September 1960. Jawaharlal Nehru signed it for India.",
 "W. A. B. Iliff signed for the World Bank.", 1),
(S, "Who was the second caliph (Khalifa) of Islam?",
 ["Hazrat Umar Farooq (RA)", "Hazrat Usman (RA)", "Hazrat Ali (RA)", "Hazrat Abu Bakr (RA)"], 0,
 "Hazrat Umar bin Khattab (RA) became the second caliph in 13 AH after being nominated by Hazrat Abu Bakr (RA). He ruled for about ten years.",
 "He was martyred in 23 AH by Abu Lulu Firoz and was succeeded by Hazrat Usman (RA).", 1),
(S, "Who was the second martial law administrator of Pakistan?",
 ["General Zia-ul-Haq", "General Yahya Khan", "General Pervez Musharraf", "Iskander Mirza"], 1,
 "Ayub Khan imposed the first martial law in October 1958. General Yahya Khan imposed the second in March 1969 when Ayub resigned.",
 "General Zia-ul-Haq imposed the third martial law in July 1977.", 1),
(S, "Who was the first Muslim woman to become a Prime Minister?",
 ["Benazir Bhutto", "Begum Khaleda Zia", "Sheikh Hasina", "Indira Gandhi"], 0,
 "Benazir Bhutto became Prime Minister of Pakistan in December 1988 and was the first woman to lead a Muslim-majority country's government. Indira Gandhi was Prime Minister of India, which is not a Muslim-majority country.",
 "She became Prime Minister again in 1993.", 1),
]
